/**
 * Country outlines generated by scripts/build-country-shapes.mjs from Natural Earth
 * (public domain, via world-atlas). Each is an SVG path fitted to its own `0 0 w h` box.
 * The data is large, so it is only reachable through `loadShapes()` (its own chunk).
 */

export type CountryShape = {
  /** SVG path data in a `0 0 w h` viewBox (draw with `fill-rule="evenodd"`). */
  d: string;
  w: number;
  h: number;
  /** 1 when every part is tiny (island specks): draw with a heavier stroke. */
  s?: number;
};

export type CountryShapes = Readonly<Record<string, CountryShape>>;

/** Load every country outline (a lazily imported chunk). */
export async function loadShapes(): Promise<CountryShapes> {
  const mod = await import('./data/shapes.json');
  return (mod.default ?? mod) as CountryShapes;
}
